import{_ as e,c as o,o as d,ai as t}from"./chunks/framework.DMRKKuRm.js";const h=JSON.parse('{"title":"Comandos Generales","description":"","frontmatter":{},"headers":[],"relativePath":"Servidor/comandos-generales.md","filePath":"Servidor/comandos-generales.md"}'),r={name:"Servidor/comandos-generales.md"};function l(i,a,n,s,c,u){return d(),o("div",null,a[0]||(a[0]=[t('<h1 id="comandos-generales" tabindex="-1">Comandos Generales <a class="header-anchor" href="#comandos-generales" aria-label="Permalink to &quot;Comandos Generales&quot;">​</a></h1><p>Esta página contiene todos los comandos disponibles en el servidor SilkCraft Network.</p><h2 id="comandos-de-chat" tabindex="-1">Comandos de Chat <a class="header-anchor" href="#comandos-de-chat" aria-label="Permalink to &quot;Comandos de Chat&quot;">​</a></h2><h3 id="mensajes-privados" tabindex="-1">Mensajes Privados <a class="header-anchor" href="#mensajes-privados" aria-label="Permalink to &quot;Mensajes Privados&quot;">​</a></h3><ul><li><code>/msg &lt;jugador&gt; &lt;mensaje&gt;</code> - Envía un mensaje privado a otro jugador</li><li><code>/r &lt;mensaje&gt;</code> - Responde al último mensaje privado recibido</li><li><code>/ignore &lt;jugador&gt;</code> - Ignora los mensajes de un jugador</li></ul><h3 id="informacion" tabindex="-1">Información <a class="header-anchor" href="#informacion" aria-label="Permalink to &quot;Información&quot;">​</a></h3><ul><li><code>/help</code> - Muestra la lista de comandos disponibles</li><li><code>/rules</code> - Muestra las reglas del servidor</li><li><code>/spawn</code> - Teletransporta al spawn</li><li><code>/home</code> - Teletransporta a tu casa</li><li><code>/sethome &lt;nombre&gt;</code> - Establece un punto de casa</li><li><code>/delhome &lt;nombre&gt;</code> - Elimina un punto de casa</li><li><code>/homes</code> - Lista todas tus casas</li></ul><h2 id="comandos-de-survival" tabindex="-1">Comandos de Survival <a class="header-anchor" href="#comandos-de-survival" aria-label="Permalink to &quot;Comandos de Survival&quot;">​</a></h2><h3 id="economia" tabindex="-1">Economía <a class="header-anchor" href="#economia" aria-label="Permalink to &quot;Economía&quot;">​</a></h3><ul><li><code>/balance</code> o <code>/bal</code> - Muestra tu balance</li><li><code>/pay &lt;jugador&gt; &lt;cantidad&gt;</code> - Paga a otro jugador</li><li><code>/baltop</code> - Muestra el top de jugadores más ricos</li></ul><h3 id="proteccion" tabindex="-1">Protección <a class="header-anchor" href="#proteccion" aria-label="Permalink to &quot;Protección&quot;">​</a></h3><ul><li><code>/claim</code> - Protege el área donde estás</li><li><code>/unclaim</code> - Desprotege un área</li><li><code>/trust &lt;jugador&gt;</code> - Da permisos a un jugador en tu claim</li><li><code>/untrust &lt;jugador&gt;</code> - Quita permisos a un jugador de tu claim</li></ul><h3 id="otros" tabindex="-1">Otros <a class="header-anchor" href="#otros" aria-label="Permalink to &quot;Otros&quot;">​</a></h3><ul><li><code>/tpa &lt;jugador&gt;</code> - Solicita teletransporte a un jugador</li><li><code>/tpahere &lt;jugador&gt;</code> - Solicita que un jugador venga a ti</li><li><code>/tpaccept</code> - Acepta una solicitud de teletransporte</li><li><code>/tpadeny</code> - Rechaza una solicitud de teletransporte</li></ul><h2 id="comandos-de-moderacion" tabindex="-1">Comandos de Moderación <a class="header-anchor" href="#comandos-de-moderacion" aria-label="Permalink to &quot;Comandos de Moderación&quot;">​</a></h2><p><em>Nota: Solo disponibles para staff</em></p><ul><li><code>/ban &lt;jugador&gt; &lt;razón&gt;</code> - Banea a un jugador</li><li><code>/kick &lt;jugador&gt; &lt;razón&gt;</code> - Expulsa a un jugador</li><li><code>/mute &lt;jugador&gt; &lt;tiempo&gt;</code> - Silencia a un jugador</li><li><code>/warn &lt;jugador&gt; &lt;razón&gt;</code> - Advierte a un jugador</li></ul><hr><p>¿Necesitas más ayuda? Visita nuestra <a href="/Servidor/faq.html">FAQ</a> o únete a nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a>.</p>',19)]))}const g=e(r,[["render",l]]);export{h as __pageData,g as default};
